package com.dtm.platform.service;import com.dtm.platform.repository.*;import com.dtm.platform.entity.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.beans.factory.annotation.Value;import jakarta.persistence.EntityManager;import java.time.*;import java.util.*;
@Service public class AnalyticsService {
 public static final Set<String> TYPES=Set.of("PAGE_VIEW","PROJECT_VIEW","RESUME_VIEW","CONTACT_SUBMISSION","ARTICLE_VIEW");private final AnalyticsEventRepository events;private final ContactMessageRepository contacts;private final EntityManager em;@Value("${app.analytics-days}")int retention;
 public AnalyticsService(AnalyticsEventRepository events,ContactMessageRepository contacts,EntityManager em){this.events=events;this.contacts=contacts;this.em=em;}
 @Transactional public void record(String type,String resource,boolean consent){if(!consent)throw new IllegalArgumentException("Consent is required");if(!TYPES.contains(type))throw new IllegalArgumentException("Unknown event type");if(resource==null||!resource.matches("[a-zA-Z0-9/_-]{1,180}"))throw new IllegalArgumentException("Invalid event resource");var e=new AnalyticsEvent();e.eventType=type;e.resource=resource;events.save(e);}
 @Transactional(readOnly=true) public Map<String,Object> summary(int days){days=Math.max(1,Math.min(days,retention));Instant since=Instant.now().minusSeconds(days*86400L);List<Object[]> totals=em.createQuery("select e.eventType,count(e) from AnalyticsEvent e where e.createdAt >= :since group by e.eventType",Object[].class).setParameter("since",since).getResultList();Map<String,Long> byType=new LinkedHashMap<>();TYPES.forEach(t->byType.put(t,0L));totals.forEach(x->byType.put((String)x[0],(Long)x[1]));var popular=em.createQuery("select e.resource,count(e) from AnalyticsEvent e where e.createdAt >= :since and e.eventType='PROJECT_VIEW' group by e.resource order by count(e) desc",Object[].class).setParameter("since",since).setMaxResults(10).getResultList().stream().map(x->Map.of("resource",x[0],"views",x[1])).toList();return Map.of("byType",byType,"popularProjects",popular,"contactLeads",contacts.count(),"days",days,"uniqueVisitorsAvailable",false,"daily",daily(since),"popularTechnologies",popularTechnologies(since));}
 private List<Map<String,Object>> daily(Instant since){var result=em.createQuery("select e.createdAt,e.eventType from AnalyticsEvent e where e.createdAt>=:since",Object[].class).setParameter("since",since).getResultList();Map<String,Long> grouped=new TreeMap<>();for(Object[] x:result){String day=((Instant)x[0]).atOffset(ZoneOffset.UTC).toLocalDate().toString();grouped.merge(day,1L,Long::sum);}return grouped.entrySet().stream().map(x->Map.<String,Object>of("date",x.getKey(),"views",x.getValue())).toList();}
 private List<Map<String,Object>> popularTechnologies(Instant since){var rows=em.createQuery("select t.name,count(e) from AnalyticsEvent e,Project p join p.technologies pt join pt.technology t where e.eventType='PROJECT_VIEW' and e.resource=p.slug and e.createdAt>=:since group by t.name order by count(e) desc",Object[].class).setParameter("since",since).setMaxResults(10).getResultList();return rows.stream().map(x->Map.<String,Object>of("name",x[0],"views",x[1])).toList();}
 @Transactional public int purge(){return em.createQuery("delete from AnalyticsEvent e where e.createdAt<:cutoff").setParameter("cutoff",Instant.now().minusSeconds(retention*86400L)).executeUpdate();}
}
